@triton.jit
def _pattern_min_pair(left, left_index, right, right_index):
    take_right = (right < left) | (right == left) & (right_index > left_index)
    return (tl.where(take_right, right, left), tl.where(take_right, right_index, left_index))

_elementwise.source:
@triton.jit
def _elementwise(X, Y, Condition, Out, COUNT: tl.constexpr, OP: tl.constexpr, BASE: tl.constexpr, SCALE: tl.constexpr, SHIFT: tl.constexpr, LOWER: tl.constexpr, UPPER: tl.constexpr, APPROXIMATE: tl.constexpr, BLOCK: tl.constexpr, X_STRIDE: tl.constexpr):
    offsets = tl.program_id(0) * BLOCK + tl.arange(0, BLOCK)
    valid = offsets < COUNT
    original = tl.load(X + offsets * X_STRIDE, valid, other=0)
    value = original.to(tl.float32)
    if OP == 'Abs':
        result = tl.abs(value)
    elif OP == 'Neg':
        result = -value
    elif OP == 'Exp':
        exponent = value * SCALE + SHIFT
        if BASE == -1.0:
            result = tl.exp(exponent)
        else:
            result = tl.exp(exponent * tl.log(BASE))
    elif OP == 'Exp2':
        result = tl.exp2(value)
    elif OP == 'Expm1':
        result = libdevice.expm1(value)
    elif OP == 'Log':
        result = tl.log(value)
    elif OP == 'Log2':
        result = tl.log2(value)
    elif OP == 'Log10':
        result = libdevice.log10(value)
    elif OP == 'Log1p':
        result = libdevice.log1p(value)
    elif OP == 'Sqrt':
        result = tl.sqrt(value)
    elif OP == 'Rsqrt':
        result = tl.rsqrt(value)
    elif OP == 'Sin':
        result = tl.sin(value)
    elif OP == 'Cos':
        result = tl.cos(value)
    elif OP == 'Tan':
        result = libdevice.tan(value)
    elif OP == 'Tanh':
        result = libdevice.tanh(value)
    elif OP == 'Sinh':
        result = libdevice.sinh(value)
    elif OP == 'Cosh':
        result = libdevice.cosh(value)
    elif OP == 'Floor':
        result = tl.floor(value)
    elif OP == 'Ceil':
        result = tl.ceil(value)
    elif OP == 'Trunc':
        result = libdevice.trunc(value)
    elif OP == 'Relu':
        result = tl.maximum(value, 0)
    elif OP == 'Sigmoid':
        result = tl.sigmoid(value)
    elif OP == 'Signbit':
        result = value.to(tl.int32, bitcast=True) < 0
    elif OP == 'BitwiseNot':
        result = ~original
    elif OP == 'Clamp':
        result = tl.minimum(tl.maximum(value, LOWER), UPPER)
    elif OP == 'Mish':
        result = value * libdevice.tanh(libdevice.log1p(tl.exp(value)))
    elif OP == 'Gelu':
        if APPROXIMATE == 'none':
            result = value * 0.5 * (1 + tl.erf(value * 0.7071067811865476))
        else:
            result = value * 0.5 * (1 + libdevice.tanh(0.7978845608028654 * (value + 0.044715 * value * value * value)))
    else:
        other_original = tl.load(Y + offsets, valid, other=1)
        other = other_original.to(tl.float32)
        if OP == 'Add':
            result = value + other
        elif OP == 'Sub':
            result = value - other
        elif OP == 'Mul':
            result = value * other
        elif OP == 'Div':
            result = value / other
        elif OP == 'FloorDiv':
            result = _floor_divide_int32(original, other_original)
        elif OP == 'Mod':
            result = original % other_original
        elif OP == 'Pow':
            result = tl.exp(other * tl.log(value))
        elif OP == 'Maximum':
            result = tl.maximum(value, other)
        elif OP == 'Minimum':
            result = tl.minimum(value, other)
        elif OP == 'Equal':
            result = value == other
        elif OP == 'NotEqual':
            result = value != other
        elif OP == 'Greater':
            result = value > other
        elif OP == 'GreaterEqual':
            result = value >= other
        elif OP == 'Less':
            result = value < other
        elif OP == 'LessEqual':
            result = value <= other
        elif OP == 'BitwiseAnd':
            result = original & other_original
        elif OP == 'BitwiseOr':
            result = original | other_original
        elif OP == 'BitwiseXor':
            result = original ^ other_original
        elif OP == 'LogicalAnd':
            result = (value != 0) & (other != 0)
        elif OP == 'LogicalOr':
            result = (value != 0) | (other != 0)
        else:
            condition = tl.load(Condition + offsets, valid, other=0)
            result = tl.where(condition, original, other_original)
    tl.store(Out + offsets, result, valid)

_rows.source:
@triton.jit
def _rows(X, Weight, Bias, Out, COLS: tl.constexpr, OP: tl.constexpr, EPSILON: tl.constexpr, BLOCK: tl.constexpr):
    row = tl.program_id(0)
    columns = tl.arange(0, BLOCK)
    valid = columns < COLS
    original = tl.load(X + row * COLS + columns, valid, other=0)
    value = original.to(tl.float32)
    if OP == 'ReduceSum' or OP == 'ReduceMean':
        result = tl.sum(value, 0)
        if OP == 'ReduceMean':
            result = result / COLS
        tl.store(Out + row, result)
    elif OP == 'ReduceMax':
        result = tl.max(tl.where(valid, value, -float('inf')), 0)
        tl.store(Out + row, result)
    elif OP == 'ReduceMin':
        result = tl.min(tl.where(valid, value, float('inf')), 0)
        tl.store(Out + row, result)
    elif OP == 'ArgMax':
        result = tl.argmax(tl.where(valid, value, -float('inf')), 0, tie_break_left=True)
        tl.store(Out + row, result.to(tl.int64))
    elif OP == 'ArgMin':
        result = tl.argmin(tl.where(valid, value, float('inf')), 0, tie_break_left=True)
        tl.store(Out + row, result.to(tl.int64))
    elif OP == 'XorSum':
        result = tl.xor_sum(original, 0)
        tl.store(Out + row, result)
    elif OP == 'CumSum':
        result = tl.cumsum(value, 0)
        tl.store(Out + row * COLS + columns, result, valid)
    elif OP == 'CumProd':
        result = tl.cumprod(tl.where(valid, value, 1.0), 0)
        tl.store(Out + row * COLS + columns, result, valid)
    elif OP == 'Softmax':
        maximum = tl.max(tl.where(valid, value, -float('inf')), 0)
        exponent = tl.where(valid, tl.exp(value - maximum), 0)
        result = exponent / tl.sum(exponent, 0)
        tl.store(Out + row * COLS + columns, result, valid)
    else:
        centered = value
        if OP == 'LayerNorm':
            mean = tl.sum(value, 0) / COLS
            centered = tl.where(valid, value - mean, 0)
        variance = tl.sum(centered * centered, 0) / COLS
        weight = tl.load(Weight + columns, valid, other=0).to(tl.float32)
        result = centered * tl.rsqrt(variance + EPSILON) * weight
        if OP == 'LayerNorm':
            bias = tl.load(Bias + columns, valid, other=0).to(tl.float32)
            result = result + bias
        tl.store(Out + row * COLS + columns, result, valid)

_layout.source:
@triton.jit
def _layout(X, Y, Out, ROWS: tl.constexpr, COLS: tl.constexpr, OTHER_COLS: tl.constexpr, OUT_COLS: tl.constexpr, OP: tl.constexpr, BLOCK: tl.constexpr):
    offsets = tl.program_id(0) * BLOCK + tl.arange(0, BLOCK)
    valid = offsets < ROWS * OUT_COLS
    row = offsets // OUT_COLS
    column = offsets % OUT_COLS
    if OP == 'Transpose':
        result = tl.load(X + offsets % ROWS * COLS + offsets // ROWS, valid, other=0)
    elif OP == 'Flip':
        result = tl.load(X + row * COLS + COLS - 1 - column, valid, other=0)
    elif OP == 'Concat':
        first = tl.load(X + row * COLS + column, valid & (column < COLS), other=0)
        second = tl.load(Y + row * OTHER_COLS + column - COLS, valid & (column >= COLS), other=0)
        result = tl.where(column < COLS, first, second)
    else:
        gate = tl.load(X + row * COLS + column, valid, other=0).to(tl.float32)
        multiplier = tl.load(X + row * COLS + OUT_COLS + column, valid, other=0).to(tl.float32)
        result = gate * tl.sigmoid(gate) * multiplier
    tl.store(Out + offsets, result, valid)

_sort.source:
@triton.jit
def _sort(X, Out, COLS: tl.constexpr, OUT_COLS: tl.constexpr, DESCENDING: tl.constexpr, BLOCK: tl.constexpr):
    row = tl.program_id(0)
    columns = tl.arange(0, BLOCK)
    if DESCENDING:
        padding = -float('inf')
    else:
        padding = float('inf')
    value = tl.load(X + row * COLS + columns, columns < COLS, other=padding).to(tl.float32)
    result = extension.sort(value, descending=DESCENDING, dim=0)
    tl.store(Out + row * OUT_COLS + columns, result, columns < OUT_COLS)

