@triton.jit
def _witness_neg(X, Out, N: tl.constexpr, STRIDE: tl.constexpr, B: tl.constexpr):
    i = tl.program_id(0) * B + tl.arange(0, B)
    x = tl.load(X + i * STRIDE, i < N, other=0)
    tl.store(Out + i, -x, i < N)
